    /// <summary>
    /// Returns full information about a supergroup or a channel by its identifier, cached for up to 1 minute
    /// </summary>
    public Task<TdLib.TdApi.Objects.SupergroupFullInfo> GetSupergroupFullInfoAsync(long supergroupId = default)
    {

           using var activity =  StartCallActivity("GetSupergroupFullInfoAsync", typeof(GetSupergroupFullInfo).FullName ?? "GetSupergroupFullInfoAsync");

           try
           {
             return client.GetSupergroupFullInfoAsync(supergroupId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
